39	export default async function Home({ searchParams }: { searchParams?: Promise<{ account?: string }> } = {}) {
40	  const params = await searchParams;
41	  const accountId = typeof params?.account === "string" ? params.account : undefined;
42	  const supabaseConfig = getSupabaseConfig();
43	  if (supabaseConfig.status !== "configured") return <main className="mx-auto max-w-3xl p-8">{supabaseConfig.detail}</main>;
44	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
45	  try {
46	    context = await requireWorkspace();
47	  } catch {
48	    redirect("/setup");
49	  }
50	  const { supabase, workspace } = context;
51	  const displayCurrency: string = workspace.display_currency;
52	  const locale = workspace.locale;
53	  const display = displayFormat(locale, workspace.timezone);
54	  const { money } = display;
55	  const today = calendarDate(new Date(), workspace.timezone);
56	  const balanceEvidencePromise = loadBalanceEvidence(supabase, workspace.id);
57	  const allWealthPromise = loadWealthItems(supabase, workspace.id, true);
58	  const wealthPromise = allWealthPromise.then(items => items.filter(item => !item.removed_at));
59	  const sourceMetadataPromise = loadSourceCoverageMetadata(supabase, workspace.id, true);
60	  // Secondary widgets start inside their Suspense boundaries after the core reads finish.
61	  const layoutPromise = Promise.resolve(supabase.from("dashboard_layouts").select("items, version, sizes").eq("workspace_id", workspace.id).maybeSingle());
62	  // Include published cards hidden from Home so Add widget can restore them without rendering their bodies.
63	  const pinnedPromise = supabase.from("artifact_cards").select("id, artifact_id, title, size, published_version, artifacts!inner(deleted_at)").eq("workspace_id", workspace.id)
64	    .is("deleted_at", null).is("artifacts.deleted_at", null).not("published_version", "is", null);
65	  const waitingPromise = loadWaitingForYou(supabase, workspace);
66	  const reviewPromise = loadReview(supabase, workspace);
67	  // First steps and the agent team point to Settings until some AI is set up; a failed check hides nothing.
68	  const aiPromise = aiConfigured().catch(() => true);
69	  const [balanceEvidence, projection, wealthItems, rates, layout, pinned, goals, allocations, sourceMetadata, allWealth, wealthEvents, bankAccounts, priceChanges] = await Promise.all([
70	    balanceEvidencePromise,
71	    evaluatePlanForWorkspace(supabase, workspace, 30, undefined, { balanceEvidence: balanceEvidencePromise, wealth: wealthPromise, sourceMetadata: sourceMetadataPromise }),
72	    wealthPromise,
73	    supabase.from("fx_rates").select("from_currency, to_currency, rate_text, rate_date, source")
74	      .eq("workspace_id", workspace.id).eq("to_currency", displayCurrency).order("rate_date", { ascending: false }).order("created_at", { ascending: false }),
