    expect(formatMoney(-10000n, "USD")).toBe("-USD 100.00");
  });

  it("formats KRW with 0 decimals", () => {
    expect(formatMoney(12345n, "KRW")).toBe("KRW 12345");
    expect(formatMoney(-12345n, "KRW")).toBe("-KRW 12345");
    expect(formatMoney(0n, "KRW")).toBe("KRW 0");
