// @vitest-environment jsdom
import { act, cleanup, render, waitFor } from "@testing-library/react";
import { afterEach, expect, it, vi } from "vitest";
import { SyncOnOpen } from "./sync-on-open";

const refresh = vi.fn();
vi.mock("next/navigation", () => ({ useRouter: () => ({ refresh }) }));
afterEach(() => { cleanup(); vi.unstubAllGlobals(); vi.clearAllMocks(); });

const answering = (body: object) => { const fetcher = vi.fn(async () => Response.json(body)); vi.stubGlobal("fetch", fetcher); return fetcher; };

it("syncs on open and updates the page only once fresher numbers landed", async () => {
  const fetcher = answering({ refresh: true });
  render(<SyncOnOpen />);
  await waitFor(() => expect(refresh).toHaveBeenCalledTimes(1));
  expect(fetcher).toHaveBeenCalledWith("/api/sync/open", { method: "POST" });
});

it("syncs again on returning to the app, and leaves the page alone when nothing ran", async () => {
  const fetcher = answering({ refresh: false });
  render(<SyncOnOpen />);
  await waitFor(() => expect(fetcher).toHaveBeenCalledTimes(1));
  await act(async () => { document.dispatchEvent(new Event("visibilitychange")); });
  await waitFor(() => expect(fetcher).toHaveBeenCalledTimes(2));
  expect(refresh).not.toHaveBeenCalled();
});

it("keeps showing the last numbers when the request fails", async () => {
  const fetcher = vi.fn(async () => { throw new Error("offline"); });
  vi.stubGlobal("fetch", fetcher);
  render(<SyncOnOpen />);
  await waitFor(() => expect(fetcher).toHaveBeenCalled());
  expect(refresh).not.toHaveBeenCalled();
});

