import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { start } from "workflow/api";
import { syncScalable } from "@/lib/scalable/sync";
import { POST } from "./route";

const tables: Record<string, Record<string, unknown>[]> = {};
vi.mock("workflow/api", () => ({ start: vi.fn(async () => ({ returnValue: Promise.resolve() })) }));
vi.mock("@/workflows/bank-sync", () => ({ syncBankConnection: vi.fn() }));
vi.mock("@/lib/bank/enable-banking", () => ({ enableBankingConfigured: async () => true }));
vi.mock("@/lib/bank/server", () => ({ psuFrom: () => ({ ip: "127.0.0.1", userAgent: "test" }) }));
vi.mock("@/lib/scalable/server", () => ({ scalableConfigured: () => true }));
vi.mock("@/lib/scalable/sync", () => ({ syncScalable: vi.fn(async () => ({})) }));
vi.mock("@/lib/auth", () => ({ requireWorkspace: async () => ({ workspace: { id: "w" }, supabase: { from: (table: string) => {
  const query = { select: () => query, eq: () => query, then: (resolve: (value: unknown) => unknown) => resolve({ data: tables[table], error: null }) };
  return query;
} } }) }));

const now = Date.parse("2026-11-08T12:00:00Z");
const ago = (minutes: number) => new Date(now - minutes * 60_000).toISOString();
const open = async () => (await POST(new Request("http://localhost/api/sync/open", { method: "POST" }))).json();
// Each test uses its own ids because the route remembers what it just tried.
const connections = (scalable: { id: string; last_synced_at: string | null }[], banks: { id: string; last_synced_at: string | null; sync_started_at?: string | null }[]) => {
  tables.scalable_connections = scalable;
  tables.bank_connections = banks.map(bank => ({ sync_started_at: null, ...bank }));
};

beforeEach(() => { vi.useFakeTimers({ now, toFake: ["Date"] }); vi.stubEnv("SUPABASE_SERVICE_ROLE_KEY", "synthetic-key"); });
afterEach(() => { vi.useRealTimers(); vi.unstubAllEnvs(); vi.clearAllMocks(); });

it("syncs Scalable after 15 minutes and a bank after an hour, as the user present, and asks for a refresh", async () => {
  connections([{ id: "s-old", last_synced_at: ago(16) }, { id: "s-new", last_synced_at: ago(14) }],
    [{ id: "b-old", last_synced_at: ago(180) }, { id: "b-new", last_synced_at: ago(59) }]);
  expect(await open()).toEqual({ refresh: true });
  expect(vi.mocked(syncScalable).mock.calls).toEqual([["s-old", "w"]]);
  expect(vi.mocked(start).mock.calls.map(call => call[1])).toEqual([["b-old", "w", { ip: "127.0.0.1", userAgent: "test" }]]);
});

it("does nothing and asks for no refresh when everything is fresh", async () => {
  connections([{ id: "s-fresh", last_synced_at: ago(1) }], [{ id: "b-fresh", last_synced_at: ago(1) }]);
  expect(await open()).toEqual({ refresh: false });
  expect(syncScalable).not.toHaveBeenCalled();
  expect(start).not.toHaveBeenCalled();
});

it("leaves a bank sync that is already running alone", async () => {
  connections([], [{ id: "b-running", last_synced_at: ago(180), sync_started_at: ago(1) }]);
  expect(await open()).toEqual({ refresh: false });
  expect(start).not.toHaveBeenCalled();
});

it("refreshes after a failed sync so Home can say so, and does not retry on every open", async () => {
  connections([{ id: "s-fails", last_synced_at: ago(600) }], []);
  vi.mocked(syncScalable).mockRejectedValueOnce(new Error("Scalable is down"));
  expect(await open()).toEqual({ refresh: true });
  expect(await open()).toEqual({ refresh: false });
  expect(syncScalable).toHaveBeenCalledTimes(1);
});

import { NextResponse } from "next/server";
import { start } from "workflow/api";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingConfigured } from "@/lib/bank/enable-banking";
import { psuFrom } from "@/lib/bank/server";
import { syncRunning } from "@/lib/bank/sync-state";
import { scalableConfigured } from "@/lib/scalable/server";
import { syncScalable } from "@/lib/scalable/sync";
import { syncBankConnection } from "@/workflows/bank-sync";

const SCALABLE_EVERY_MS = 15 * 60_000, BANK_EVERY_MS = 60 * 60_000;
// Tries that have not stamped last_synced_at yet: other tabs, or a sync that failed.
const tried = new Map<string, number>();
function due(connection: { id: string; last_synced_at: string | null }, everyMs: number) {
  const now = Date.now();
  const last = Math.max(connection.last_synced_at ? Date.parse(connection.last_synced_at) : 0, tried.get(connection.id) ?? 0);
  if (now - last < everyMs) return false;
  tried.set(connection.id, now);
  return true;
}

// Opening or returning to Moneo: the page already shows the last numbers, and this answers once fresher ones have landed.
// The owner is present, so bank fetches carry PSU headers and don't use the background allowance. Failures are kept on the connection.
export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  const { supabase, workspace } = context;
  const [scalable, banks] = await Promise.all([
    supabase.from("scalable_connections").select("id, last_synced_at").eq("workspace_id", workspace.id).eq("status", "active"),
    supabase.from("bank_connections").select("id, last_synced_at, sync_started_at").eq("workspace_id", workspace.id).eq("status", "active"),
  ]);
  if (scalable.error || banks.error) return NextResponse.json({ error: "Connections are unavailable" }, { status: 503 });
  const syncs: Promise<unknown>[] = [];
  if (scalableConfigured()) for (const row of scalable.data ?? []) if (due(row, SCALABLE_EVERY_MS)) syncs.push(syncScalable(row.id, workspace.id));
  if ((banks.data ?? []).length && process.env.SUPABASE_SERVICE_ROLE_KEY && await enableBankingConfigured()) for (const row of banks.data ?? [])
    if (!syncRunning(row) && due(row, BANK_EVERY_MS)) syncs.push(start(syncBankConnection, [row.id, workspace.id, psuFrom(request)]).then(run => run.returnValue));
  await Promise.allSettled(syncs);
  return NextResponse.json({ refresh: syncs.length > 0 });
}

"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";

/** Syncs when Moneo is opened or returned to, and updates the page once fresher numbers land. Renders nothing. */
export function SyncOnOpen() {
  const router = useRouter();
  useEffect(() => {
    const sync = async () => {
      if (document.visibilityState !== "visible") return;
      const response = await fetch("/api/sync/open", { method: "POST" }).catch(() => null);
      if (response?.ok && (await response.json()).refresh) router.refresh();
    };
    void sync();
    document.addEventListener("visibilitychange", sync);
    return () => document.removeEventListener("visibilitychange", sync);
  }, [router]);
  return null;
}

