// Read-only probe. Only ever calls the tools in ALLOWED. Prints shapes, not amounts.
import { serviceDb } from "@/lib/bank/server";
import { withScalable } from "@/lib/scalable/server";

const ALLOWED = new Set(["list_portfolio_transactions", "get_security_chart"]);
const mask = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.length ? [mask(value[0]), `…${value.length}`] : [];
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, mask(v)]));
  return typeof value;
};

async function main() {
  const db = serviceDb();
  const { data } = await db.from("scalable_connections").select("id, workspace_id").eq("status", "active").single();
  await withScalable(data!.id, data!.workspace_id, async mcp => {
    const tools = await mcp.listTools();
    console.log("TOOLS", tools.map(tool => tool.name).join(", "));
    for (const tool of tools) if (/transaction|chart|history|perform|valuation|overview/i.test(tool.name)) console.log(tool.name, JSON.stringify((tool as { inputSchema?: unknown }).inputSchema));
    const call = (name: string, args: Record<string, unknown>) => { if (!ALLOWED.has(name)) throw new Error("blocked " + name); return mcp.callTool(name, args); };
    console.log("TX SHAPE", JSON.stringify(mask(await call("list_portfolio_transactions", { pageSize: 5 }))));
  });
}
main().catch(error => { console.error(String(error)); process.exit(1); });

