// Read-only probe: cash gap, crypto, chart resolution. Calls only ALLOWED tools.
import { serviceDb } from "@/lib/bank/server";
import { withScalable } from "@/lib/scalable/server";
const ALLOWED = new Set(["list_portfolio_transactions", "get_security_chart", "get_portfolio_holdings", "get_portfolio_cash_breakdown", "get_portfolio_overview", "get_transaction_details", "get_overnight_summary", "list_overnight_transactions"]);
type Row = Record<string, any>;
const mask = (value: unknown): unknown => { if (Array.isArray(value)) return value.length ? [mask(value[0]), `…${value.length}`] : []; if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, mask(v)])); return value === null ? "null" : typeof value; };
async function main() {
  const { data } = await serviceDb().from("scalable_connections").select("id, workspace_id").eq("status", "active").single();
  await withScalable(data!.id, data!.workspace_id, async mcp => {
    const call = (name: string, args: Record<string, unknown> = {}) => { if (!ALLOWED.has(name)) throw new Error("blocked " + name); return mcp.callTool(name, args) as Promise<Row>; };
    const all: Row[] = [], crypto: Row[] = []; let cursor: string | undefined, cc: string | undefined, n = 0;
    do { const p = await call("list_portfolio_transactions", { pageSize: 100, ...(cursor ? { cursor } : {}), ...(cc ? { cryptoCursor: cc } : {}) }); all.push(...(p.transactions ?? [])); crypto.push(...(p.crypto?.transactions ?? [])); cursor = p.page?.nextCursor ?? undefined; cc = p.crypto?.page?.nextCursor ?? undefined; n++; } while ((cursor || cc) && n < 100);
    console.log("IDS", { rows: all.length, uniqueIds: new Set(all.map(r => r.id)).size, crypto: crypto.length, uniqueCrypto: new Set(crypto.map(r => r.id)).size });
    const amt = (r: Row) => Number((r.security ?? r.cash ?? r.nonTradeSecurity ?? r.eltif ?? {}).amount ?? 0);
    const sum = (rows: Row[], f: (r: Row) => number) => rows.reduce((s, r) => s + f(r), 0);
    const cash = await call("get_portfolio_cash_breakdown"), over = await call("get_portfolio_overview");
    console.log("CASH KEYS", JSON.stringify(mask(cash)));
    const bal = Number(cash.cash.cashBalance), secCash = sum(all, amt), cryptoAmt = sum(crypto, r => Number(r.amount ?? 0));
    console.log("GAP", { "withoutCrypto-balance": (secCash - bal).toFixed(2), "withCrypto-balance": (secCash + cryptoAmt - bal).toFixed(2), cryptoSum: cryptoAmt.toFixed(2) });
    const byDate = [...all].map(r => ({ d: r.lastEventAt, a: amt(r) })).concat(crypto.map(r => ({ d: r.lastEventAt, a: Number(r.amount ?? 0) }))).sort((a, b) => a.d.localeCompare(b.d));
    let run = 0, low = 0, lowAt = ""; for (const r of byDate) { run += r.a; if (run < low) { low = run; lowAt = r.d.slice(0, 10); } }
    console.log("RUNNING cash", { lowest: low.toFixed(2), lowAt, end: run.toFixed(2) });
    console.log("CRYPTO ROWS", crypto.map(r => ({ d: r.lastEventAt?.slice(0, 10), coin: r.coinQuantity, qty: r.quantity, ticker: r.ticker })));
    const holdings = await call("get_portfolio_holdings");
    const heldCoins = (holdings.cryptoHoldings ?? []).filter((c: Row) => (c.position?.filled ?? 0) > 0);
    console.log("CRYPTO", { catalog: holdings.cryptoHoldings?.length, held: heldCoins.map((c: Row) => ({ ticker: c.ticker, etp: c.etpPositions?.length })), overviewCrypto: over.valuation?.crypto, overviewKeys: Object.keys(over.valuation ?? {}) });
    console.log("OVERNIGHT", await call("get_overnight_summary").then(v => JSON.stringify(mask(v))).catch(e => String(e).slice(0, 120)));
    const isin = holdings.holdings[0].isin;
    for (const timeframe of ["one_day", "seven_days", "one_month", "three_months", "six_months", "year_to_date", "one_year", "max"]) {
      const c = await call("get_security_chart", { isin, timeframe }); const t = (c.dataPoints ?? []).map((p: Row) => Date.parse(p.timestampUtc)).sort((a: number, b: number) => a - b);
      const g = t.slice(1).map((v: number, i: number) => (v - t[i]) / 86400000).sort((a: number, b: number) => a - b);
      console.log("RES", timeframe, { points: t.length, first: t[0] ? new Date(t[0]).toISOString().slice(0, 10) : null, medianGapDays: g[g.length >> 1]?.toFixed(3), maxGap: g.at(-1)?.toFixed(2), cur: c.currency });
    }
    const currencies = new Set<string>(); for (const h of holdings.holdings) currencies.add(`${h.currentQuote.currency}/${h.valuationCurrency}`); console.log("HELD CURRENCIES", [...currencies]);
    const anySplit = all.filter(r => r.nonTradeSecurity).length; console.log("NONTRADE ROWS", anySplit, "ELTIF", all.filter(r => r.eltif).length);
    const tx = all.find(r => r.security); if (tx) console.log("DETAIL SHAPE", JSON.stringify(mask(await call("get_transaction_details", { transactionId: tx.id }))).slice(0, 1200));
  });
}
main().catch(error => { console.error(String(error)); process.exit(1); });
EOF
