cd /c/codebases/Moneo && S="/c/Users/mgsuk/AppData/Local/Temp/claude/3de23844519d7b87/a53c00e3-302d-4a6a-8526-8a16f8ccd815/scratchpad"; cat > "$S/scalable-probe-5.ts" <<'EOF'
// Read-only probe: how the crypto ETP position and its price are reported. Calls only ALLOWED tools.
import { serviceDb } from "@/lib/bank/server";
import { withScalable } from "@/lib/scalable/server";
const ALLOWED = new Set(["get_portfolio_holdings", "get_portfolio_overview", "get_security_chart"]);
type Row = Record<string, any>;
async function main() {
  const { data } = await serviceDb().from("scalable_connections").select("id, workspace_id").eq("status", "active").single();
  await withScalable(data!.id, data!.workspace_id, async mcp => {
    const call = (name: string, args: Record<string, unknown> = {}) => { if (!ALLOWED.has(name)) throw new Error("blocked " + name); return mcp.callTool(name, args) as Promise<Row>; };
    const h = await call("get_portfolio_holdings"), o = await call("get_portfolio_overview");
    const btc = (h.cryptoHoldings ?? []).find((c: Row) => c.ticker === "BTC");
    console.log("BTC ETPS", JSON.stringify(btc.etpPositions));
    console.log("OTHER COINS WITH ANY ETP POSITION", (h.cryptoHoldings ?? []).filter((c: Row) => c.ticker !== "BTC" && (c.etpPositions ?? []).some((e: Row) => e.position)).length);
    console.log("ETP ALSO IN SECURITIES", (h.holdings ?? []).some((x: Row) => x.isin === "CH0454664001"));
    const c = await call("get_security_chart", { isin: "CH0454664001", timeframe: "one_day" }); const last = c.dataPoints.at(-1);
    console.log("ETP", { currency: c.currency, lastPrice: last?.midPrice, tenShares: Number(last?.midPrice) * 10, overviewCrypto: o.valuation?.crypto });
  });
}
main().catch(error => { console.error(String(error)); process.exit(1); });
EOF
