1	import { expect, it } from "vitest";
2	import { calculateHistory, readHistoryInput, type HistoryInput } from "./history";
3	
4	const ISIN = "DE000A0TEST1", ETP = "XS0000000ETP";
5	const buy = (id: string, at: string, quantity: string, amount: string, isin = ISIN) => ({ id, at, kind: "security" as const, isin, side: "BUY", quantity, amountText: amount });
6	const sell = (id: string, at: string, quantity: string, amount: string, isin = ISIN) => ({ id, at, kind: "security" as const, isin, side: "SELL", quantity, amountText: amount });
7	const cash = (id: string, at: string, amount: string) => ({ id, at, kind: "cash" as const, amountText: amount });
8	const coin = (id: string, at: string, side: string, coins: string, amount: string, ticker = "BTC") => ({ id, at, kind: "crypto" as const, ticker, side, quantity: coins, amountText: amount });
9	const chart = (...points: [string, number][]) => ({ currency: "EUR", points: points.map(([at, price]) => ({ at, price: String(price) })) });
10	
11	const input = (over: Partial<HistoryInput> = {}): HistoryInput => ({
12	  rows: [cash("d", "2026-01-01T09:00:00Z", "100"), buy("b", "2026-01-02T10:00:00Z", "2", "-20")],
13	  charts: { [ISIN]: chart(["2026-01-03T17:00:00Z", 11], ["2026-01-05T17:00:00Z", 12]) }, coinCharts: {},
14	  holdings: [{ isin: ISIN, filled: 2, currency: "EUR" }], coins: [], cashBalance: 80, cryptoValue: 0, timeZone: "UTC", before: "2026-01-06", ...over,
15	});
16	const failed = (over: Partial<HistoryInput>) => { const result = calculateHistory(input(over)); expect(result.ok).toBe(false); return result.ok ? "" : result.reason; };
17	const days = (over: Partial<HistoryInput> = {}) => { const result = calculateHistory(input(over)); if (!result.ok) throw new Error(result.reason); return result.days; };
18	
19	it("values each day from the first transaction through the day before the first sync, using the latest price and never interpolating", () => {
20	  expect(days().map(day => [day.date, day.securitiesMinor, day.cashMinor, day.totalMinor])).toEqual([
21	    ["2026-01-01", 0n, 10000n, 10000n],
22	    ["2026-01-02", 2000n, 8000n, 10000n], // the trade's own price
23	    ["2026-01-03", 2200n, 8000n, 10200n],
24	    ["2026-01-04", 2200n, 8000n, 10200n], // a gap in the chart keeps the last price
25	    ["2026-01-05", 2400n, 8000n, 10400n],
26	  ]);
27	});
28	
29	it("signs shares by side, adds exact decimals and keeps selling on the right side", () => {
30	  const rows = [cash("d", "2026-01-01T09:00:00Z", "100"), buy("b", "2026-01-01T10:00:00Z", "0.1", "-1"), buy("c", "2026-01-01T11:00:00Z", "0.2", "-2"), sell("s", "2026-01-02T10:00:00Z", "0.1", "1.5")];
31	  const result = days({ rows, holdings: [{ isin: ISIN, filled: 0.2, currency: "EUR" }], cashBalance: 98.5, charts: { [ISIN]: chart() }, before: "2026-01-03" });
32	  expect(result.map(day => [day.securitiesMinor, day.cashMinor])).toEqual([[300n, 9700n], [300n, 9850n]]);
33	});
34	
35	it("uses the workspace's calendar day for transactions and prices", () => {
36	  // 23:30 UTC on Jan 1 is already Jan 2 in Berlin.
37	  const rows = [cash("d", "2026-01-01T23:30:00Z", "100"), buy("b", "2026-01-02T23:30:00Z", "2", "-20")];
38	  const over = { rows, charts: { [ISIN]: chart(["2026-01-03T23:30:00Z", 15]) }, before: "2026-01-05" };
39	  expect(days({ ...over, timeZone: "Europe/Berlin" }).map(day => [day.date, day.totalMinor])).toEqual([["2026-01-02", 10000n], ["2026-01-03", 10000n], ["2026-01-04", 11000n]]);
40	  expect(days({ ...over, timeZone: "UTC" }).map(day => [day.date, day.totalMinor])).toEqual([["2026-01-01", 10000n], ["2026-01-02", 10000n], ["2026-01-03", 11000n], ["2026-01-04", 11000n]]);
41	});
42	
