  await withScalable(conn!.id, conn!.workspace_id, async mcp => { let c: string | undefined; do { const p = await mcp.callTool("list_portfolio_transactions", { pageSize: 100, ...(c ? { cursor: c } : {}) }) as Row; rows.push(...(p.transactions ?? [])); c = p.page?.nextCursor || undefined; } while (c); });
  const byId = new Map(rows.map(r => [r.id, r]));
  const ret = rows.filter(r => /^RETURN-/.test(r.id));
  console.log("RETURN rows", ret.length, "with matching opposite withdrawal", ret.filter(r => { const o = byId.get(r.id.replace(/^RETURN-/, "")); return o && Number(o.cash?.amount) === -Number(r.cash?.amount); }).length, "sample types", [...new Set(ret.map(r => r.cash?.transactionType))]);
  const ev = await loadBalanceEvidence(db as never, conn!.workspace_id);
  for (const opts of [undefined, { preferLatestRecorded: true }] as const) console.log(opts ? "loose" : "strict", JSON.stringify(resolveBalances(ev.accounts, ev.snapshots, ev.ledger, ev.asOf, "Europe/Berlin", undefined, opts).map((a: any) => [a.name.slice(0, 10), a.balance.amount_minor, a.balance.status ?? a.balance.state ?? null])));
}
main().catch(e => { console.error(e); process.exit(1); });
