11	/** The model's view of a balance the user states: a decimal amount; the application turns it into exact minor units. */
12	export const balanceInputSchema = z.object({
13	  account: z.string().trim().min(1).max(120).optional().describe("The account's name, e.g. 'Wallet EUR'. Omit for cash: the currency's single cash account, or a new Cash account when there is none"),
14	  amount: z.string().trim().regex(/^-?\d{1,15}(\.\d{1,4})?$/).describe("The balance as a decimal, e.g. 115 or 1250.40"),
15	  currency: z.string().regex(/^[A-Z]{3}$/),
16	  asOf: z.iso.date().optional().describe("The date the balance was true; defaults to today"),
17	}).strict();
18	
19	/** A null accountId means the accepted proposal creates the currency's Cash account first. */
20	export const balanceSetSchema = z.object({
21	  accountId: z.uuid().nullable(), amountMinor: z.string().regex(/^-?\d{1,18}$/), currencyCode: z.string().regex(/^[A-Z]{3}$/), asOf: z.iso.date(),
22	}).strict();
23	
24	/** Stores a pending "set this account's balance" proposal. Nothing changes until the owner accepts. */
