182	    </header>
183	    <div class="scenes">
184	
185	<!-- 1 · Title -->
186	<section class="scene" data-title="Phone access" data-short="Intro">
187	  <div class="hero">
188	    <div>
189	      <p class="eyebrow">Moneo · open-source personal finance · deep dive</p>
190	      <h1>Phone access</h1>
191	      <p class="lede" style="margin-top:22px;font-size:24px">How a phone or tablet becomes another screen on the Moneo running on your computer, without putting your money on the internet.</p>
192	      <div class="stack-tags">
193	        <span>Tailscale Serve</span><span>WireGuard</span><span>Next.js 16</span><span>HTTPS</span><span>Add to Home Screen</span>
194	      </div>
195	    </div>
196	    <div class="mock" aria-hidden="true">
197	      <div class="card" style="left:30px;top:40px;width:470px;height:300px">
198	        <span class="pill">Laptop · runs Moneo</span>
199	        <h3>Net worth</h3>
200	        <div class="big" style="margin-top:8px">€ 24,180</div>
201	        <svg viewBox="0 0 400 90" style="width:100%;margin-top:18px"><path d="M0 70 C50 60 70 72 110 55 S170 30 210 42 270 18 300 26 370 8 400 12" fill="none" stroke="var(--brand)" stroke-width="3"/></svg>
202	      </div>
203	      <div class="card" style="left:360px;top:190px;width:190px;height:350px;border-radius:30px;border:2px solid var(--fg)">
204	        <span class="pill p-brand">Phone</span>
205	        <h3>Net worth</h3>
206	        <div class="big" style="font-size:30px;margin-top:8px">€ 24,180</div>
207	        <svg viewBox="0 0 140 70" style="width:100%;margin-top:18px"><path d="M0 55 C20 48 30 56 50 42 S80 22 95 30 120 10 140 8" fill="none" stroke="var(--brand)" stroke-width="3"/></svg>
208	        <p style="margin-top:18px">Same data, same screen</p>
