291	    <div class="card" data-s="6">
292	      <h3>On the phone or tablet</h3>
293	      <ul class="ticks" style="margin-top:12px">
294	        <li>Install Tailscale and sign in with the same account</li>
295	        <li>Scan the code in Settings</li>
296	        <li>Choose Add to Home Screen</li>
