461	// One page per scene: everything on it fades in by itself, in its data-s order, so only a scene change needs a key.
462	function render() {
463	  scenes.forEach((s, i) => s.classList.toggle("on", i === index));
464	  const s = scenes[index];
465	  const parts = [...s.querySelectorAll("[data-s]")];
466	  parts.forEach(e => { e.classList.remove("shown"); e.style.transitionDelay = `${(+e.dataset.s - 1) * 90}ms`; });
467	  requestAnimationFrame(() => requestAnimationFrame(() => parts.forEach(e => e.classList.add("shown"))));
468	  [...rail.querySelectorAll("button")].forEach((b, i) => b.setAttribute("aria-current", i === index));
469	  document.getElementById("crumb").innerHTML = `<strong>${String(index + 1).padStart(2, "0")}</strong> / ${scenes.length} · ${s.dataset.title}`;
470	  document.getElementById("bar").style.width = `${((index + 1) / scenes.length) * 100}%`;
471	  try { history.replaceState(null, "", `#${index + 1}`); } catch {}
472	}
473	function go(i) { index = Math.max(0, Math.min(scenes.length - 1, i)); render(); }
474	function next() { if (index < scenes.length - 1) go(index + 1); }
475	function prev() { if (index > 0) go(index - 1); }
476	
477	addEventListener("keydown", e => {
478	  if (["ArrowRight", "PageDown", " ", "Enter"].includes(e.key)) { e.preventDefault(); next(); }
479	  else if (["ArrowLeft", "PageUp", "Backspace"].includes(e.key)) { e.preventDefault(); prev(); }
480	  else if (e.key === "Home") go(0);
481	  else if (e.key === "End") go(scenes.length - 1);
482	  else if (e.key.toLowerCase() === "d") setTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark");
483	  else if (e.key.toLowerCase() === "f") document.fullscreenElement ? document.exitFullscreen() : document.documentElement.requestFullscreen?.();
484	  else if (e.key.toLowerCase() === "r") document.body.classList.toggle("hide-rail");
485	});
