1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	import { z } from "zod";
4	import { formatMoney } from "@/lib/finance/format";
5	import { loadWorkspaceSettings } from "@/lib/settings";
6	
7	// Money moved between the owner's own accounts is a transfer, never income or spending.
8	// Detection is deterministic and IBAN-only: a row's counterparty IBAN is one of the owner's
9	// own accounts. Every decision goes through the audited link RPCs, so each one can be undone.
10	
11	export const MATCH_DAYS = 3;
12	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
13	
14	export function normalizeIban(value: string) {
15	  const iban = value.replace(/\s/g, "").toUpperCase();
16	  return IBAN.test(iban) ? iban : null;
17	}
18	
19	/** Every IBAN-shaped value in an original source row (counterparty columns differ per bank). */
20	export function sourceIbans(row: unknown) {
21	  if (!row || typeof row !== "object") return [];
22	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
23	}
24	
25	export type TransferCandidate = {
26	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
27	  reviewReasons: string[]; ibans: string[]; text?: string; counterparty?: string;
28	};
29	
30	// Without an IBAN, only the bank's own wording proves own money: a cash machine, or Scalable Capital
31	// once the owner connected Scalable (their withdrawals arrive without the broker's IBAN).
32	const CASH = /\b(bargeldauszahlung|bargeldeinzahlung|geldautomat|cash withdrawal|atm withdrawal|cash deposit)\b/i;
33	const SCALABLE = /\bscalable capital\b/i;
34	export type NamedAccount = "cash" | "scalable";
35	export const NAMED_LABELS: Record<NamedAccount, string> = { cash: "Cash", scalable: "Scalable Capital" };
36	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string> }; // IBAN → account id / identifier id
37	
38	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
39	
40	/** Every posted leg in the workspace, so a lone leg can tell whether its other side exists. */
41	export type Leg = Pick<TransferCandidate, "id" | "accountId" | "postedOn" | "amountMinor" | "currencyCode">;
42	
43	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows, options: { scalable?: boolean } = {}) {
44	  // The posting account's own IBAN often appears in its row too; only the other side counts.
45	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
46	  const points = (row: TransferCandidate, accountId: string) => counterparts(row).some(iban => own.tracked.get(iban) === accountId);
47	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
48	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
49	  const used = new Set<string>();
50	  const pairs: { outId: string; inId: string }[] = [];
51	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
52	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
53	
54	  // IBAN-proven pairs first, closest date wins.
55	  for (const out of outs) {
56	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
57	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
58	    if (!used.has(out.id) && proven[0]) take(out, proven[0]);
59	  }
60	  // A leg whose other side is missing: the counterparty is an own account, and no opposite
61	  // leg exists in that account within the window. Untracked accounts are named by identifier;
62	  // tracked accounts by IBAN.
63	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
64	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
65	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
66	    if (used.has(row.id)) return [];
67	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
68	    if (identifierId) return [{ transactionId: row.id, identifierId }];
69	    const iban = counterparts(row).find(item => own.tracked.has(item));
70	    const accountId = iban ? own.tracked.get(iban) : undefined;
71	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
72	  });
73	  const marked = new Set(single.map(item => item.transactionId));
74	  const named = rows.flatMap((row): { transactionId: string; account: NamedAccount }[] => {
75	    if (used.has(row.id) || marked.has(row.id) || counterparts(row).some(iban => own.tracked.has(iban) || own.untracked.has(iban))) return [];
76	    if (CASH.test(row.text ?? "")) return [{ transactionId: row.id, account: "cash" }];
77	    if (options.scalable && SCALABLE.test(`${row.counterparty ?? ""} ${row.text ?? ""}`)) return [{ transactionId: row.id, account: "scalable" }];
78	    return [];
79	  });
80	  return { pairs, single, named };
81	}
82	
83	const nameKey = (name: string) => name.normalize("NFD").replace(/\p{M}/gu, "").replace(/\s+/g, " ").trim().toLowerCase();
84	
85	/**
86	 * Rows from a name the owner already sent money under to one of their own IBANs (their name on an old or
87	 * untracked account). A name alone is weak evidence, so these are only ever suggestions for the owner to accept.
88	 * `seen` are rows that already prove an own account (including linked transfers); `answered` already have a card.
89	 */
90	export function ownNameSuggestions(rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts, answered = new Set<string>()) {
91	  const names = new Map<string, string>();
92	  for (const row of seen) {
93	    const other = row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
94	    if (row.counterparty?.trim() && other.some(iban => own.tracked.has(iban) || own.untracked.has(iban))) names.set(nameKey(row.counterparty), row.counterparty.trim());
95	  }
96	  // A bank can put the holder's own name on a payment with no real other side (Revolut card refunds);
97	  // a transfer the owner made names them in the description too.
98	  return rows.flatMap(row => {
99	    const name = row.counterparty ? names.get(nameKey(row.counterparty)) : undefined;
100	    return name && !answered.has(row.id) && nameKey(row.text ?? "").includes(nameKey(name)) ? [{ transactionId: row.id, name }] : [];
101	  });
102	}
103	
104	const PAGE = 1000, MAX_ROWS = 5000;
105	
106	export async function loadOwnAccounts(db: SupabaseClient, workspaceId: string): Promise<OwnAccounts> {
107	  const [identifiers, bank, accounts] = await Promise.all([
108	    db.from("own_account_identifiers").select("id, account_id, iban").eq("workspace_id", workspaceId),
109	    db.from("bank_connection_accounts").select("iban, account_name, currency_code").eq("workspace_id", workspaceId).not("iban", "is", null),
110	    db.from("accounts").select("id, name, currency_code").eq("workspace_id", workspaceId),
111	  ]);
112	  for (const result of [identifiers, bank, accounts]) if (result.error) throw new Error(result.error.message);
113	  const tracked = new Map<string, string>(), untracked = new Map<string, string>();
114	  // A bank sync imports into the account with the bank's name and currency (see bankAccountNames).
115	  for (const row of bank.data ?? []) {
116	    const account = accounts.data?.find(item => item.name === row.account_name && item.currency_code === row.currency_code);
117	    const iban = normalizeIban(row.iban ?? "");
118	    if (account && iban) tracked.set(iban, account.id);
119	  }
120	  for (const row of identifiers.data ?? []) {
121	    if (row.account_id) tracked.set(row.iban, row.account_id); else untracked.set(row.iban, row.id);
122	  }
123	  return { tracked, untracked };
124	}
125	
126	type Row = { id: string; version: number; account_id: string; posted_on: string; amount_minor: string; currency_code: string; review_reasons: string[] | null; description: string;
127	  transaction_sources: { source_transactions: { original_row: unknown } | null }[] | null };
128	
129	/** The counterparty name a bank sync stores on its original row; other imports leave it out. */
130	const counterpartyOf = (row: unknown) => {
131	  const value = row && typeof row === "object" ? (row as { counterparty?: unknown }).counterparty : undefined;
132	  return typeof value === "string" && value.trim() ? value.trim() : undefined;
133	};
134	
135	async function loadRows(db: SupabaseClient, workspaceId: string, kind: "ordinary" | "transfer") {
136	  const rows: TransferCandidate[] = [];
137	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
138	    let query = db.from("transactions")
139	      .select("id, version, account_id, posted_on, amount_minor::text, currency_code, review_reasons, description, transaction_sources(source_transactions(original_row))")
140	      .eq("workspace_id", workspaceId).eq("status", "posted").eq("kind", kind);
141	    if (kind === "ordinary") query = query.is("transfer_id", null).is("refund_of_id", null);
142	    const { data, error } = await query.order("posted_on", { ascending: false }).order("id").range(from, from + PAGE - 1);
143	    if (error) throw new Error(error.message);
144	    for (const row of (data ?? []) as unknown as Row[]) {
145	      const reviewReasons = row.review_reasons ?? [];
146	      if (kind === "ordinary" && reviewReasons.some(reason => reason !== "source_transfer")) continue;
147	      const originals = (row.transaction_sources ?? []).map(source => source.source_transactions?.original_row);
148	      rows.push({ id: row.id, version: row.version, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor),
149	        currencyCode: row.currency_code, reviewReasons, ibans: [...new Set(originals.flatMap(sourceIbans))], text: row.description, counterparty: originals.map(counterpartyOf).find(Boolean) });
150	    }
151	    if ((data ?? []).length < PAGE) break;
152	  }
153	  return rows;
154	}
155	
156	export const loadTransferCandidates = (db: SupabaseClient, workspaceId: string) => loadRows(db, workspaceId, "ordinary");
157	
158	/** Every posted leg, whatever its review state, so a lone leg can see whether its other side exists. */
159	async function loadLegs(db: SupabaseClient, workspaceId: string): Promise<Leg[]> {
160	  const legs: Leg[] = [];
161	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
162	    const { data, error } = await db.from("transactions")
163	      .select("id, account_id, posted_on, amount_minor::text, currency_code")
164	      .eq("workspace_id", workspaceId).eq("status", "posted").order("id").range(from, from + PAGE - 1);
165	    if (error) throw new Error(error.message);
166	    for (const row of data ?? []) legs.push({ id: row.id, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code });
167	    if ((data ?? []).length < PAGE) break;
168	  }
169	  return legs;
170	}
171	
172	export const ownTransferPayloadSchema = z.object({ transactionId: z.uuid(), name: z.string().trim().min(1).max(120) }).strict();
173	
174	/** Raises one "your own money?" card per row, once: a declined card is never raised again. */
175	async function proposeOwnNames(db: SupabaseClient, workspaceId: string, rows: TransferCandidate[], seen: TransferCandidate[], own: OwnAccounts) {
176	  const known = await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).is("run_id", null).eq("kind", "own_transfer").limit(5000);
177	  if (known.error) throw new Error(known.error.message);
178	  const answered = new Set((known.data ?? []).map(row => String(row.conflict_key).replace(/^own_transfer:/, "")));
179	  const found = ownNameSuggestions(rows, seen, own, answered);
180	  if (!found.length) return 0;
181	  const { locale } = await loadWorkspaceSettings(db, workspaceId);
182	  const byId = new Map(rows.map(row => [row.id, row]));
183	  const cards = found.map(({ transactionId, name }) => {
184	    const row = byId.get(transactionId)!, money = formatMoney(row.amountMinor < 0n ? -row.amountMinor : row.amountMinor, row.currencyCode, locale);
185	    return { workspace_id: workspaceId, agent: "chat", kind: "own_transfer", conflict_key: `own_transfer:${transactionId}`, confidence: 70,
186	      title: (row.amountMinor < 0n ? `${money} to ${name}: your own account?` : `${money} from ${name}: your own account?`).slice(0, 200),
187	      detail: `You sent money under the name ${name} to one of your own accounts before. If this is yours too, it moves to transfers and stops counting as ${row.amountMinor < 0n ? "spending" : "income"}.`,
188	      evidence: { facts: [], transactions: [{ id: row.id, date: row.postedOn, description: row.text ?? "", amountMinor: row.amountMinor.toString(), currency: row.currencyCode }], links: [] },
189	      payload: ownTransferPayloadSchema.parse({ transactionId, name }) };
190	  });
191	  const { data, error } = await db.from("agent_proposals").insert(cards).select("id");
192	  // A concurrent sync raised the same card first.
193	  if (error && error.code !== "23505") throw new Error(error.message);
194	  return data?.length ?? 0;
195	}
196	
197	/** Find and link transfers between the owner's accounts. The service role acts for the owner. */
198	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
199	  const [own, rows, legs, transfers, scalable] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId),
200	    loadRows(db, workspaceId, "transfer"), db.from("scalable_connections").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "active")]);
201	  if (scalable.error) throw new Error(scalable.error.message);
202	  const { pairs, single, named } = findOwnTransfers(rows, own, legs, { scalable: (scalable.count ?? 0) > 0 });
203	  const byId = new Map(rows.map(row => [row.id, row]));
204	  let linked = 0, marked = 0, skipped = 0;
205	  for (const pair of pairs) {
206	    const out = byId.get(pair.outId)!, into = byId.get(pair.inId)!;
207	    // The RPC rejects pairs it can't prove (e.g. a documented fee); those stay for manual review.
208	    const { error } = await db.rpc("link_transactions", { p_operation: "transfer", p_primary_id: out.id, p_expected_version: out.version,
209	      p_other_id: into.id, p_other_version: into.version, p_fx_rate_id: null, p_fees: [], p_request_id: randomUUID() });
210	    if (error) skipped++; else linked++;
211	  }
212	  for (const item of single) {
213	    const expectedVersion = byId.get(item.transactionId)!.version;
214	    const { error } = item.identifierId
215	      ? await db.rpc("mark_own_account_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_identifier_id: item.identifierId })
216	      : await db.rpc("mark_own_iban_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_iban: item.iban });
217	    if (error) skipped++; else marked++;
218	  }
219	  for (const item of named) {
220	    const { error } = await db.rpc("mark_own_named_transfer", { p_transaction_id: item.transactionId, p_expected_version: byId.get(item.transactionId)!.version, p_kind: item.account });
221	    if (error) skipped++; else marked++;
222	  }
223	  const handled = new Set([...pairs.flatMap(pair => [pair.outId, pair.inId]), ...single.map(item => item.transactionId), ...named.map(item => item.transactionId)]);
224	  const suggested = await proposeOwnNames(db, workspaceId, rows.filter(row => !handled.has(row.id)), [...rows, ...transfers], own);
225	  return { linked, marked, skipped, suggested };
226	}
