import { createRequire } from "node:module";
const require = createRequire("file:///C:/codebases/Moneo/");
const { chromium } = require("@playwright/test");
const out = "C:/Users/mgsuk/AppData/Local/Temp/claude/3de23844519d7b87/a53c00e3-302d-4a6a-8526-8a16f8ccd815/scratchpad/nw-doc";
const theme = process.argv[2] ?? "light";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1600, height: 900 }, colorScheme: theme });
await page.goto("file:///C:/codebases/Moneo/docs/net-worth-deep-dive.html");
const n = await page.locator(".scene").count();
for (let i = 1; i <= n; i++) {
  await page.evaluate(k => go(k), i - 1);
  await page.waitForTimeout(1500);
  const r = await page.evaluate(() => {
    const scene = document.querySelector(".scene.on"), box = scene.getBoundingClientRect(), bad = [];
    for (const el of scene.querySelectorAll("*")) { if (el.closest("svg") && el.tagName !== "svg") continue; const b = el.getBoundingClientRect(); if (b.height && (b.bottom > box.bottom - 16 || b.right > box.right - 40)) bad.push(`${el.tagName}.${el.className}: bottom ${Math.round(b.bottom - box.bottom)} right ${Math.round(b.right - box.right)}`); }
    const clipped = [...scene.querySelectorAll(".node,.card")].filter(e => e.scrollHeight > e.clientHeight + 1).length;
    return { title: scene.dataset.title, bad: bad.slice(0, 3), clipped };
  });
  console.log(i, r.title, r.bad.length ? "OVERFLOW " + r.bad.join(" | ") : "fits", r.clipped ? `clippedCards=${r.clipped}` : "");
  await page.screenshot({ path: `${out}-${theme}-${String(i).padStart(2, "0")}.png` });
}
await browser.close();

